// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.deny(address(this));
        bool ok;
        try c.rely(address(0x1)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Buggy mutant should have allowed the call, but reference reverts");
    }
}
